import { MeshBasicNodeMaterial, PlaneGeometry } from 'three/webgpu';
import { vec2 } from 'three/tsl';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as text from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, Vector2 } = ctx.THREE;

  // Create a container group (allows future children)
  const root = new Group();

  // Determine atlas region and aspect ratio
  const atlasRect = config.atlasRegion?.sourceRect ?? [0, 0, 512, 320];
  const [, , regionW, regionH] = atlasRect;
  const aspect = regionW / regionH;

  // Plane geometry sized to aspect ratio (height = 1 unit)
  const geometry = new PlaneGeometry(aspect, 1, 1, 1);

  // Adjust UVs to map only the specified atlas region (assuming full texture size = region size)
  // If the atlas is larger, the following will still map the full texture correctly.
  const uOffset = atlasRect[0] / regionW;
  const vOffset = atlasRect[1] / regionH;
  const uScale = regionW / regionW;
  const vScale = regionH / regionH;
  const uvs = geometry.getAttribute('uv');
  for (let i = 0; i < uvs.count; i++) {
    const u = uvs.getX(i);
    const v = uvs.getY(i);
    uvs.setXY(i, u * uScale + uOffset, v * vScale + vOffset);
  }
  uvs.needsUpdate = true;

  // Create material (basic, unlit)
  const material = new MeshBasicNodeMaterial();
  material.transparent = true;
  material.depthWrite = false;

  // Load texture asynchronously; apply when ready
  const texturePromise = ctx.textureLoader.loadTexture(config.imageUrl);
  texturePromise.then((tex) => {
    material.map = tex;
    material.needsUpdate = true;
  });

  // Mesh
  const mesh = new Mesh(geometry, material);
  mesh.renderOrder = 0;

  // Billboard: always face camera
  mesh.onBeforeRender = (renderer, scene, camera) => {
    mesh.lookAt(camera.position);
  };

  // Attach handlers container
  root.userData.handlers = {};

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose geometry and material
    geometry.dispose();
    material.dispose();
    // Dispose texture if loaded
    texturePromise.then((tex) => tex.dispose());
    // Kill any GSAP timelines (none in this node but safe)
    gsap.globalTimeline.clear();
  };

  root.add(mesh);
  return root;
}
